            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest_corner(src, w, h):
        corners = [[0, 0], [0, h - 1], [w - 1, 0], [w - 1, h - 1]]
        best = corners[0]
        best_d = manhattan(src, best)
        for c in corners[1:]:
            d = manhattan(src, c)
            if d > best_d:
                best = c
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = safe_pos(observation.get("self_position"), [0, 0])
    opp_pos = safe_pos(observation.get("opponent_position"), [self_pos[0], self_pos[1]])
    w = observation.get("grid_width", 0)
