        if tgt is None:
            return [0, 0]
        return step_toward(self_pos, tgt)

    resources = []
    for key in ("resources", "resource_positions", "items", "food"):
        vals = observation.get(key) or []
        for v in vals:
            p = as_pair(v)
            if p is not None:
                resources.append(p)

